const GLOSSARY=[
 ['Accettazione','Manifestazione di volontà conforme alla proposta che può concludere il contratto.'],['Agibilità','Segnalazione riferita a condizioni richieste di sicurezza, igiene, salubrità e conformità dell’opera.'],['APE','Attestato della prestazione energetica dell’edificio o unità.'],['Caparra confirmatoria','Somma o quantità di cose fungibili con funzione di garanzia del contratto, art. 1385 c.c.'],['Caparra penitenziale','Corrispettivo convenuto per l’esercizio del diritto di recesso.'],['Catasto','Inventario tecnico-fiscale degli immobili.'],['CDU','Certificato di destinazione urbanistica dei terreni.'],['Cedolare secca','Regime fiscale sostitutivo opzionale per determinati contratti di locazione.'],['CILA','Comunicazione di inizio lavori asseverata per determinati interventi edilizi.'],['Comodato','Contratto di concessione gratuita di una cosa, con obbligo di restituzione.'],['Condominio','Coesistenza di proprietà esclusive e parti comuni di un edificio.'],['Conservatoria','Denominazione tradizionale degli uffici di pubblicità immobiliare.'],['Controproposta','Risposta che modifica la proposta iniziale e vale come nuova proposta.'],['DOCFA','Procedura di aggiornamento del Catasto fabbricati.'],['Diritto di superficie','Diritto di costruire e mantenere costruzione su suolo altrui in separazione dalla proprietà del suolo.'],['Estimo','Disciplina che fornisce criteri e metodi di valutazione economica.'],['Evizione','Perdita del bene acquistato per effetto di un diritto prevalente di terzi.'],['Fideiussione','Garanzia personale con cui un soggetto garantisce un’obbligazione altrui.'],['Immobile collabente','Unità in stato di forte degrado, frequentemente censita F/2.'],['Ipoteca','Diritto reale di garanzia che normalmente si costituisce per iscrizione.'],['LTV','Loan to Value: rapporto percentuale tra finanziamento e valore di riferimento dell’immobile.'],['Mandato','Contratto in cui una parte si obbliga a compiere atti giuridici per conto dell’altra.'],['Mediatore','Chi mette in relazione parti per concludere affari senza i vincoli tipici indicati all’art. 1754 c.c.'],['Millesimi','Valore proporzionale delle unità in condominio per le finalità previste.'],['Nuda proprietà','Proprietà di un bene gravata da usufrutto.'],['OMI','Osservatorio del Mercato Immobiliare, Agenzia delle Entrate.'],['PGT','Piano di Governo del Territorio: strumento urbanistico comunale lombardo.'],['PREGEO','Procedura per atti geometrici di aggiornamento del Catasto terreni.'],['Preliminare','Contratto che obbliga alla successiva stipula di un definitivo.'],['Prescrizione','Estinzione di un diritto per inerzia protratta per il tempo previsto, salvo eccezioni.'],['Prezzo-valore','Sistema fiscale che in certi acquisti consente di usare il valore catastale come base imponibile.'],['Procura','Atto che conferisce un potere di rappresentanza.'],['Provvigione','Compenso del mediatore quando l’affare si conclude per effetto del suo intervento.'],['REA','Repertorio delle notizie economiche e amministrative.'],['Rendita catastale','Valore fiscale attribuito ai fabbricati secondo le regole catastali.'],['RLI','Modello per registrazione e altri adempimenti dei contratti di locazione.'],['Rogito','Atto notarile che formalizza frequentemente un trasferimento immobiliare.'],['SCIA','Segnalazione certificata di inizio attività, usata in diversi regimi amministrativi.'],['Servitù','Peso su un fondo per l’utilità di un altro fondo di diverso proprietario.'],['TAEG','Indicatore del costo annuo complessivo del credito secondo la normativa.'],['TAN','Tasso annuo nominale degli interessi.'],['Trascrizione','Formalità nei registri immobiliari che rende opponibili determinati atti ai terzi.'],['Usucapione','Acquisto di diritti mediante possesso protratto con i requisiti di legge.'],['Usufrutto','Diritto di godere un bene altrui nel rispetto della destinazione economica.'],['Voltura','Aggiornamento delle intestazioni catastali.']
];

